import test from 'node:test';import assert from 'node:assert/strict';import {reviewAgenda} from '../../reda-2/review-agenda.mjs';
test('agenda puts symptom and contact facts before exercise friction',()=>{const a=reviewAgenda({digest:{valid:true,flags:[{kind:'exercise',label:'Benspark',detail:'2 × för tung'},{kind:'contact',label:'x'},{kind:'symptoms',label:'x'}]}});assert.deepEqual(a.items.map(x=>x.kind),['symptoms','contact','exercise'])});
test('agenda deduplicates same factual category from digest and delta',()=>{const a=reviewAgenda({digest:{valid:true,flags:[{kind:'contact',label:'Patienten har bett om hjälp'}]},delta:{changes:[{kind:'contact',label:'Önskemål om hjälp',before:0,after:1}]}});assert.equal(a.items.filter(x=>x.kind==='contact').length,2)});
test('agenda is capped and reports remaining items',()=>{const flags=Array.from({length:7},(_,i)=>({kind:'exercise',exerciseId:'e'+i,label:'Övning '+i}));const a=reviewAgenda({digest:{valid:true,flags},max:4});assert.equal(a.items.length,4);assert.equal(a.overflow,3)});
test('empty registered evidence creates no invented task',()=>{const a=reviewAgenda({digest:{valid:true,flags:[]}});assert.equal(a.empty,true);assert.equal(a.items.length,0)});
